class Solution:
    def lastMarkedNodes(self, edges: List[List[int]]) -> List[int]:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b); adj[b].append(a)
        def bfs(src):
            dist = [-1] * n; dist[src] = 0
            q = [src]
            for u in q:
                for v in adj[u]:
                    if dist[v] < 0:
                        dist[v] = dist[u] + 1; q.append(v)
            far = max(range(n), key=lambda j: dist[j])
            return dist, far
        return [max(range(n), key=lambda j: bfs(i)[0][j]) for i in range(n)]

