class Solution {
public:
    vector<int> lastMarkedNodes(vector<vector<int>>& edges) {
        int n = edges.size() + 1;
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        auto bfs = [&](int src) {
            vector<int> dist(n, -1); dist[src] = 0;
            queue<int> q; q.push(src);
            int far = src;
            while (!q.empty()) {
                int u = q.front(); q.pop();
                if (dist[u] > dist[far]) far = u;
                for (int v : adj[u]) if (dist[v] < 0) { dist[v] = dist[u] + 1; q.push(v); }
            }
            return make_pair(dist, far);
        };
        vector<int> res;
        for (int i = 0; i < n; i++) {
            auto [d, f] = bfs(i);
            res.push_back(f);
        }
        return res;
    }
};

