class Solution {
    private List<List<Integer>> adj;
    private int[] bfs(int src, int n) {
        int[] dist = new int[n]; Arrays.fill(dist, -1);
        Deque<Integer> q = new ArrayDeque<>(); q.add(src); dist[src] = 0;
        int far = src;
        while (!q.isEmpty()) {
            int u = q.poll();
            if (dist[u] > dist[far]) far = u;
            for (int v : adj.get(u)) if (dist[v] < 0) { dist[v] = dist[u] + 1; q.add(v); }
        }
        dist[0] = far; // reuse slot 0 to carry farthest node
        int[] out = new int[n + 1]; System.arraycopy(dist, 0, out, 1, n); out[0] = far;
        return out;
    }
    public int[] lastMarkedNodes(int[][] edges) {
        int n = edges.length + 1;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] r1 = bfs(0, n); int u = r1[0];
        int[] duFull = bfs(u, n); int v = duFull[0];
        int[] du = Arrays.copyOfRange(duFull, 1, n + 1);
        int[] dvFull = bfs(v, n);
        int[] dv = Arrays.copyOfRange(dvFull, 1, n + 1);
        int[] res = new int[n];
        for (int i = 0; i < n; i++) res[i] = du[i] >= dv[i] ? u : v;
        return res;
    }
}

